from collections import Counter
n = len(S); d = [s[1] - s[0] for s in S]; sets = Counter(s[2] for s in S); sizes = Counter(s[3] for s in S); moves = sum(1 for s in S if 'push' in s[4] or 'pull' in s[4] or 'pan' in s[4])
L = ['# David & Nathan: shot list v2', '',
     f'{n} shots over 102 s (was 34). Median {sorted(d)[n // 2]:.2f} s, longest {max(d):.2f} s. Built to `library/styles/CLAY_CAMERA_SPEC.md`.', '',
     f'- **Sets:** throne room {sets["T"]} · paper theatre {sets["P"]} · modern {sets["M"]}',
     f'- **Sizes:** ' + ' · '.join(f'{k} {v}' for k, v in sizes.most_common()) + f' (inserts {100 * sizes["INS"] // n}%)',
     f'- **Camera moves:** {moves} of {n} ({100 * moves // n}%); the rest are locked or a subtle drift',
     '- **Already built and tested:** the five-shot verdict (47–52 s) and the lamb grab (27–32 s)', '',
     '| # | Time | Set | Shot | Camera | Picture | Narration |', '|---|---|---|---|---|---|---|']
for i, s in enumerate(S, 1): L.append(f'| {i} | {s[0]:.2f}–{s[1]:.2f} | {dict(T="Throne", P="Paper", M="Modern")[s[2]]} | {s[3]} | {s[4]} | {s[5]} | "{s[6]}" |')
open('production/david/SHOTLIST_v2.md', 'w').write('\n'.join(L) + '\n'); print('\n'.join(L[:8]))
